def skill():
    a = Symbol('a')
    sol = [k for k in range(-60, 61) if k*k - (3*k + 4) <= 0]
    return sum(sol)

def standard():
    x = Symbol('x', real=True)
    tot, cnt = 0, 0
    for k in range(-40, 41):
        fp = x**2 + 2*k*x + 3*k + 4
        ok = solve_univariate_inequality(fp >= 0, x, relational=False) == S.Reals
        if ok:
            tot += k
            cnt += 1
    assert cnt == 6
    return tot

def unique():
    return [standard()]
